Level "1" -- "*" GridPosition : uses
Level "1" -- "*" Block : contains
GameSession "*" -- "1" Game : belongs to
GameSession "1" -- "1" ScoreEntry : records in
HallOfFame "1" -- "*" ScoreEntry : contains

@enduml

